    def check_probability_bounds(cls, v: float) -> float:
        if v < 0.0 or v > 1.0:
            raise ValueError(f"Metric score {v} must be between 0.0 and 1.0")
        return round(v, 4)

    def mean_score(self) -> float:
        items = self.__root__
        return sum(items) / len(items) if items else 0.0


