from typing import Generic, TypeVar, List, Dict, Any
from pydantic import BaseModel, field_validator, model_validator, RootModel, TypeAdapter

PayloadT = TypeVar("PayloadT")


class BatchMetricVector(RootModel[List[float]]):
    root: List[float]

    @field_validator("root")
    @classmethod
    def check_probability_bounds(cls, v: List[float]) -> List[float]:
        validated = []
        for item in v:
            if item < 0.0 or item > 1.0:
                raise ValueError(f"Metric score {item} must be between 0.0 and 1.0")
            validated.append(round(item, 4))
        return validated

    def mean_score(self) -> float:
        items = self.root
        return sum(items) / len(items) if items else 0.0


class EnvelopeContext(BaseModel, Generic[PayloadT]):
    trace_id: str
    attempt_count: int = 1
    payload: PayloadT
    scores: BatchMetricVector

    model_config = {
        "arbitrary_types_allowed": True,
    }

    @field_validator("attempt_count")
    @classmethod
    def check_attempt_limit(cls, v: int) -> int:
        if v > 5:
            raise ValueError(f"Field attempt_count exceeded max retry limit of 5")
        return v

    @model_validator(mode="after")
    def verify_payload_integrity(self) -> "EnvelopeContext":
        trace = self.trace_id
        if trace.startswith("ERR_") and self.attempt_count == 1:
            self.attempt_count = 2
        return self


def parse_envelope_batch(raw_list: List[Dict[str, Any]]) -> List[EnvelopeContext[Dict[str, Any]]]:
    parsed = TypeAdapter(List[EnvelopeContext[Dict[str, Any]]]).validate_python(raw_list)
    return parsed

