from datetime import datetime
from typing import Optional, Dict, Any, Self
from pydantic import BaseModel, Field, ConfigDict, ValidationInfo, field_serializer, field_validator, model_validator


class BaseFinancialModel(BaseModel):
    transaction_id: str
    created_at: datetime = Field(default_factory=datetime.utcnow)
    model_config = ConfigDict(validate_assignment=True)
    @field_serializer("*", mode="plain", when_used="json")
    def _serialize_json_encoders(self, value):
        _encoders = {
        Decimal: lambda v: str(round(v, 2)),
        datetime: lambda v: v.isoformat(),
}
        for _typ, _enc in _encoders.items():
            if isinstance(value, _typ):
                return _enc(value)
        return value


class HighRiskWireTransfer(BaseFinancialModel):
    sender_country: str = Field(..., min_length=2, max_length=2)
    receiver_country: str = Field(..., min_length=2, max_length=2)
    amount_usd: Decimal = Field(..., gt=Decimal("0.00"))
    fx_rate: Optional[Decimal] = Field(default = None, validate_default = True)
    requires_manual_compliance_review: bool = False
    compliance_notes: Optional[str] = None

    @model_validator(mode="before")
    @classmethod
    def normalize_country_codes_and_amounts(cls, data: Dict[str, Any]) -> Dict[str, Any]:
        if isinstance(data, dict):
            for key in ("sender_country", "receiver_country"):
                if key in data and isinstance(data[key], str):
                    data[key] = data[key].strip().upper()
            if "amount_usd" in data and isinstance(data["amount_usd"], (int, float)):
                data["amount_usd"] = Decimal(str(data["amount_usd"]))
        return data

    @field_validator("fx_rate")
    @classmethod
    def validate_cross_border_fx_rate(cls, v: Optional[Decimal], info: ValidationInfo) -> Decimal:
        sender = info.data.get("sender_country")
        receiver = info.data.get("receiver_country")
        if sender and receiver and sender != receiver:
            if v is None or v <= Decimal("0"):
                raise ValueError("Cross-border transfers require a positive fx_rate")
            return v
        return v or Decimal("1.0000")

    @model_validator(mode="after")
    def enforce_high_value_compliance_policy(self) -> Self:
        amount = getattr(self, "amount_usd", Decimal("0"))
        sender = getattr(self, "sender_country", None)
        receiver = getattr(self, "receiver_country", None)

        if amount >= Decimal("10000.00") or (sender != receiver and amount >= Decimal("3000.00")):
            self.requires_manual_compliance_review = True
            if not getattr(self, "compliance_notes", None):
                self.compliance_notes = "Auto-flagged by cross-border risk threshold"
        return self

    def export_compliance_snapshot(self) -> Dict[str, Any]:
        raw = self.model_dump(exclude_none=False)
        raw["serialized_json"] = self.model_dump_json()
        return raw

